import Image from "next/image";
import { SITE } from "@/lib/config/site";
import { cn } from "@/lib/utils";

/**
 * Brand lockup and standalone gear mark.
 *
 * Assets are generated by `npm run brand:assets`. Height drives the rendered
 * size so `next/image` emits a tight srcset instead of scaling the 1800px
 * source down in the browser.
 */

const ASSETS = {
  lockup: {
    ratio: 1800 / 688,
    onLight: "/brand/wordmark-dark.png",
    onDark: "/brand/wordmark-light.png",
  },
  mark: {
    ratio: 1,
    onLight: "/brand/mark-dark.png",
    onDark: "/brand/mark-light.png",
  },
} as const;

type AppLogoProps = {
  /** Full wordmark, or the gear glyph alone for tight spaces. */
  shape?: keyof typeof ASSETS;
  /**
   * `on-light` and `on-dark` name the surface the logo sits on. `auto` swaps
   * with the theme class and is only needed inside the role panels, since
   * marketing and auth routes are locked to light.
   */
  tone?: "auto" | "on-light" | "on-dark";
  /**
   * Accessible name. Defaults to the public brand; pass `SITE.systemName` in
   * role panels so screen readers hear the Management System name.
   */
  label?: string;
  /** Rendered height in pixels. */
  height?: number;
  className?: string;
  priority?: boolean;
};

export function AppLogo({
  shape = "lockup",
  tone = "on-light",
  label = SITE.name,
  height = 32,
  className,
  priority = false,
}: AppLogoProps) {
  const asset = ASSETS[shape];
  const width = Math.round(height * asset.ratio);

  const image = (src: string, extraClassName?: string) => (
    <Image
      src={src}
      alt=""
      width={width}
      height={height}
      priority={priority}
      className={cn("object-contain", extraClassName)}
    />
  );

  return (
    <span
      role="img"
      aria-label={label}
      className={cn("inline-flex shrink-0 items-center", className)}
    >
      {tone === "on-dark" ? null : image(asset.onLight, tone === "auto" ? "dark:hidden" : undefined)}
      {tone === "on-light" ? null : image(asset.onDark, tone === "auto" ? "hidden dark:block" : undefined)}
    </span>
  );
}
